    """Find translated occurrences of the marked 8-shape in zero cells."""
    h, w = len(grid), len(grid[0])
    marker = 8
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    if not points:
        return [row[:] for row in grid]
    r0 = min(r for r, c in points)
    c0 = min(c for r, c in points)
    shape = [(r-r0, c-c0) for r, c in points]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            cells = [(r+dr, c+dc) for dr, dc in shape]
            if all(0 <= rr < h and 0 <= cc < w and grid[rr][cc] == 0 for rr, cc in cells):
                for rr, cc in cells:
                    out[rr][cc] = marker
    return out
